INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-deer-hunting', 132159, '2020-01-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co235y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ctj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Deer Hunting', 'See what it''s really like to hunt whitetail deer in one of four different North American venues! Pro mode provides the same challenges that you would encounter if you were actually in the woods. Ultimate success requires you to harvest each of the four whitetail deer sub-species that are offered in the game. To provide further challenge there are three different firearms choices as well as bow hunting! Action mode provides more of a deer drive style of hunt. The objective in this style of hunt is more about quick and accurate shooting. Combine this with photo-realistic graphics and accurate depictions of the environments and you have the ultimate virtual deer hunting experience. There is something for each style but to earn the platinum you have to master everything!' FROM games WHERE igdb_id = 132159 ON CONFLICT (game_id, language_code) DO NOTHING;
