INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kids: Farm Coloring', 'Do you like animals? Yes! Do you like painting? Yes! This game is for you! Kids: Farm Coloring lets you paint all the most popular farming animals! From a duck to pig, from a sheep to cow! Have you seen a funny colorful chicken? A smiling donkey in a rainbow? Everything is possible! The sky is the limit. Want to try your own drawings? Let''s take a blank sheet to unleash your creativity and draw freely! All the painting tools are here for you! So, what are you going to paint now?' FROM games WHERE igdb_id = 147783 ON CONFLICT (game_id, language_code) DO NOTHING;
