INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('echoes-of-aeons', 139142, '2020-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2hc1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8lna.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echoes of Aeons', 'At the edge of the Universe the Aeons set about to create and to destroy. What was left in the wake was the children of Terra, unified and prosperous... Until the breaking of the world. Follow Rinelesca "Rin" Stellaris, The daughter heir to the throne of Lusec, as she is caught in the midst of a brewing war, after celebrating centuries of peace in her home nation. As tensions rise, Rin sets out on her own to figure out the cause of the goings on in Terra. As she inches closer to uncovering the truth, what she thought was myth slowly becomes reality. And Eldric Estellion A young man orphaned in his youth, unbeknownst to him, he is one of the Descended. A fabled people born of mortal and Aeonic blood. Thrown into a world beyond possibility, Eldric must find the courage to face his deepest fears. Is it destiny or choice in which one’s life is framed? A tale of two souls, bound together by fate, as they challenge destiny in an epic tale of time and space, love, laughter, the human condition and those who seek to destroy existence.' FROM games WHERE igdb_id = 139142 ON CONFLICT (game_id, language_code) DO NOTHING;
