INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sister-splash', 205999, '2020-09-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wds.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schktc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sister Splash', 'You were once a celebrated swimming champion until you suffered a traumatic experience that''s kept you away from water ever since. You thought your swimming career was over until you were asked to transfer schools and become the coach of an all-girls swim team. The girls are all pretty cute, but the only trouble is these girls can''t seem to agree on anything. You soon discover why, when you learn the swim teams three key swimmers are triplets!
