INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BOT.vinnik Chess: Opening Traps', 'Do you think Queen''s Gambit is a TV series, comrade? WRONG! It is a Chess opening! If you don''t even know that, you have a lot to learn! A good chess player should know the chess openings and, more important, how to avoid their traps! Enroll NOW and find out how!' FROM games WHERE igdb_id = 163686 ON CONFLICT (game_id, language_code) DO NOTHING;
