INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Decommissioner', 'You are the Decommissioner - tasked with defeating the rogue AI MurderBot by gathering the tools/weapons you need while the MurderBot and it''s minions are out to destroy you. Weapons and Equipment are OSP (On Site Procurement), but this is no sneaking mission. If you fail, try again, and the more enemies you defeat, the more equipment will be unlocked to find in the field.' FROM games WHERE igdb_id = 186252 ON CONFLICT (game_id, language_code) DO NOTHING;
