INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rocket Rabbit - Coin Race', 'Help Rocket Rabbit race through the hills and tunnels chasing after coins! Go upside down in the rabbit tunnels and defy gravity! Jump to avoid the other running rabbits, sleeping turtles, crawling spiders and climbing groundhogs! Or jump on top of them to earn extra coins! Use coins to buy powerups that will help you last longer and race further! Use cool powerups like invincibility, slo-mo and super speed to enhance your gameplay! Rocket Rabbit is endless racing fun for the entire family!' FROM games WHERE igdb_id = 147866 ON CONFLICT (game_id, language_code) DO NOTHING;
