INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Quiet Death', 'A tie-in game with the Mythic Quest episode of the same name. The episode chronicles the development of Dark Quiet Death, as well as the life and relationship of its creators. The game itself is a simple first-person horror arcade game, survive as long as possible in a maze, using a flashlight to drive off monsters.' FROM games WHERE igdb_id = 185869 ON CONFLICT (game_id, language_code) DO NOTHING;
