INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Ninja', 'The Legend of Ninja is a 2D Action-RPG Platformer. The game aims to immerse you in its fantasy world full of deadly traps, various enemies and mysteries to discover. Player impersonate as fearless ninja passing through dangerous fantasy worlds on his mission to rescue his beloved princess who got kidnapped by a Dracula from her castle. Journey into the unknown as an unskilled fighter with each step, each defeated enemy and boss will bring crucial experience in order to prepare young warrior in his final battle against powerful vampire.' FROM games WHERE igdb_id = 147947 ON CONFLICT (game_id, language_code) DO NOTHING;
