INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Mikio Hiraiwa-Supervised Yomu Tore GO!', 'Dr. Mikio Hiraiwa-Supervised Yomu Tore GO! is for people with dyslexia and with reading difficulties. It has three training methods: reading letters aloud by using the included microphone, recognizing letters as units of sounds, and turning the sounds into letters. There are prepared 6 games, 54 levels, and 227 stages.' FROM games WHERE igdb_id = 145389 ON CONFLICT (game_id, language_code) DO NOTHING;
