INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liu Jie Mi Ti', '失意青年刘在机缘巧合下得到了一份离奇的工作，在命运齿轮的推动下，结识了几名性格各异的少女。忽然有一天祸从天降，他卷入了一起绑架案，并被迫参与一场事关生死的游戏。在求生的同时，他不得不重新审视过去生活寻求蛛丝马迹，那看似平静的生活实则早已暗流涌动……' FROM games WHERE igdb_id = 127537 ON CONFLICT (game_id, language_code) DO NOTHING;
