INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grievance', 'Grievance is an interactive story about power. The limits of power, its corrosive nature, and the damage that power inflicts, deliberate or otherwise, on all those without it. Follow the lives of three characters as their paths cross and untangle over the course of the story: the aging farmer Cole, the faithful knight Hiram, and the royal heiress Sera.' FROM games WHERE igdb_id = 135614 ON CONFLICT (game_id, language_code) DO NOTHING;
