INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carthanc', 'You play as an astronaut sent to the planet Carthanc on a top secret mission, hidden from the public. Is there life on Carthanc? If so, is it friendly? Can Carthanc sustain human life? Is it a viable candidate to terraform? Time for you to find out! You are tasked with collecting samples, filming footage, deploying tech, and determining if any life exists.' FROM games WHERE igdb_id = 281867 ON CONFLICT (game_id, language_code) DO NOTHING;
