INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nerdook-bundle-vol-1', 147664, '2020-03-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5amw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbrb.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nerdook Bundle Vol. 1', 'One-man indie developer Nerdook is a master at making games that are easy to pick up and play, but impossible to put down. This collection includes three Nerdook gems: Monster Slayers, Reverse Crawl, and Vertical Drop Heroes. Monster Slayers: A rogue-like deck-building RPG adventure with an innovative card-based battle system. Choose your path through the perilous Northern Valley as you follow your quest to defeat the legendary Harbinger. Reverse Crawl: You’re dead already! But that isn’t going to stop you – the Revenant King – from reclaiming your throne. This fast-paced turn-based strategy RPG that lets you lead mobs of monster minions and back-from-the-grave goons into battle. Vertical Drop Heroes: A procedural platformer RPG hybrid with roguelike elements. Armed with a variety of skills and traits, use your cunning and reflexes to survive the dangers of each stage, until you face the final boss and uncover the truth behind the game!' FROM games WHERE igdb_id = 147664 ON CONFLICT (game_id, language_code) DO NOTHING;
