INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PuzzlePolygons', 'PuzzlePolygons is a top down puzzle game, designed to infuriate. The original score purposely created for the game is eerie and cryptic, and the game is challenging. Have fun trying to finish it! The game fits in with the reset theme, as the screen is constantly resetting/restarting.' FROM games WHERE igdb_id = 153605 ON CONFLICT (game_id, language_code) DO NOTHING;
