INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Penny''s Path', 'In this voice-acted, hand-painted visual novel about women and witchcraft, a brush with the coronavirus sends Penny back in time to the New England witch hunts. As Penny meets strong female characters who challenge past and present stereotypes, she discovers her own special role in the changing seasons of time.' FROM games WHERE igdb_id = 161608 ON CONFLICT (game_id, language_code) DO NOTHING;
