INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Water Balloon Mania', '"Water Balloon Mania" is an addictive puzzle game. The goal is to remove all fires from the screen. To do that you have to rotate and position the water balloons on top of or alongside the fires and other water balloons so that there are at least 4 blocks with the same color next to each other. You can move and turn the water balloons with the joypad.' FROM games WHERE igdb_id = 147467 ON CONFLICT (game_id, language_code) DO NOTHING;
