INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('singularity--2', 171896, '2020-12-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5l7q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar149g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singularity', '‘Singularity’ is an immersive virtual reality experience that combines technologies including 3D scanning, head-mounted display, and immersive sound design. Creating an abandoned and forgotten world by designing a decentralized order, it invites the audience to rethink the relationship between living organism and inorganic intelligence. The inspiration for this work grows from the artist''s personal experience of living an accelerating digitized world. She creatively associates the relationship between racing games and Moore''s Law, also The Law of Accelerating Returns that appeared in the human’s technology development history.' FROM games WHERE igdb_id = 171896 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 171896 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
