INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Connect Four', 'Connect Four is the strategy game that we all know and love. You play against a computer opponent in connecting, you guess it, 4 pieces before your opponent does. The pieces can be connected vertically, horizontally, and even diagonally. You have the option to play as red or yellow as well as choosing your difficulty level.' FROM games WHERE igdb_id = 313549 ON CONFLICT (game_id, language_code) DO NOTHING;
