INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'B.O.O.M.: You Win', 'B.O.O.M. You Win is an explosive hot potato party game for one to four players where players gain points by holding onto an explosive ball for as long as possible before it explodes. Players must dodge their opponents and avoid explosives as they try to maintain control of the objective without being blown to pieces in the process. Featuring a simple pick up and play control scheme, B.O.O.M. is an explosive good time for players of all skill levels,' FROM games WHERE igdb_id = 134770 ON CONFLICT (game_id, language_code) DO NOTHING;
